<script>
  let text = $state("Hello world");

  // Basic $inspect to log the input value
  $inspect(text);

  // $inspect(...).with to track updates with custom callback
  $inspect(text).with((value) => {
    console.log("Text changed to:", value);
  });

  // $inspect.trace() inside an effect
  $effect(() => {
    $inspect.trace();
    console.log("Effect ran, text is:", text);
  });
</script>

